api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.company-profile {
  background: #ffffff;
  border-radius: 12px;
  overflow: hidden;
  font-family: Arial, sans-serif;
}

.profile-header {
  background: linear-gradient(135deg, #f5f3ff, #eef2ff);
  padding: 28px 30px;
  border: 1px solid #e4e1ff;
  border-radius: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.section-label {
  color: #4f46e5;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.profile-header h1 {
  margin: 0;
  color: #111827;
  font-size: 28px;
  font-weight: 700;
}

.profile-header p {
  margin: 7px 0 0;
  color: #6b7280;
  font-size: 14px;
}

.status-badge {
  background: #dcfce7;
  color: #15803d;
  padding: 9px 15px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
}

.status-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  background: #22c55e;
  border-radius: 50%;
  margin-right: 6px;
}

.company-content {
  margin-top: 18px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 28px;
  background: #ffffff;
}

.company-title {
  display: flex;
  align-items: center;
  gap: 15px;
  padding-bottom: 24px;
  border-bottom: 1px solid #eeeef5;
}

.company-icon {
  width: 55px;
  height: 55px;
  border-radius: 14px;
  background: #5b5ce2;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 23px;
  font-weight: 700;
}

.company-title h2 {
  margin: 0;
  color: #111827;
  font-size: 21px;
}

.company-title p {
  margin: 5px 0 0;
  color: #6b7280;
  font-size: 13px;
}

.details-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-top: 24px;
}

.detail-card {
  background: #fafaff;
  border: 1px solid #ececf7;
  border-radius: 10px;
  padding: 17px;
}

.detail-card span {
  display: block;
  color: #7c7c91;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .5px;
  margin-bottom: 7px;
}

.detail-card strong {
  color: #1f2937;
  font-size: 14px;
}

.not-found {
  margin-top: 18px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 70px 20px;
  text-align: center;
}

.not-found-icon {
  width: 40px;
  height: 40px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: #ede9fe;
  color: #6366f1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  font-size: 20px;
}

.not-found h2 {
  margin: 0 0 8px;
  color: #111827;
  font-size: 17px;
}

.not-found p {
  margin: 0;
  color: #73738a;
  font-size: 13px;
}

@media (max-width: 700px) {

  .details-grid {
    grid-template-columns: 1fr;
  }

  .profile-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 15px;
  }

}

sp_widget.script:
(function() {

    data.company = null;

    var email = gs.getUser().getEmail();

    var gr = new GlideRecord('x_snc_campus360_company_master');
    gr.addQuery('recruiter_email', email);
    gr.addQuery('status', 'Active');
    gr.query();

    if (gr.next()) {

        data.company = {
            company_name: gr.getValue('company_name'),
            company_id: gr.getValue('company_id'),
            company_type: gr.getDisplayValue('company_type'),
            industry: gr.getDisplayValue('industry'),
            recruiter_name: gr.getValue('recruiter_name'),
            recruiter_email: gr.getValue('recruiter_email'),
            contact_number: gr.getValue('contact_number'),
            status: gr.getDisplayValue('status')
        };

    }

})();
